function Analytics({data,all}:{data:Incident[];all:Incident[]}){const [period,setPeriod]=useState<'day'|'week'|'month'>('month'),[compare,setCompare]=useState('All areas');const cats=groupCount(data,x=>x.category),severity=groupCount(data,x=>x.severity).map(x=>({...x,fill:sevColor(x.name)}));const hourlyData=hourly(data),days=weekdays(data),series=trend(data,period);const areaData=groupCount(data.filter(x=>compare==='All areas'||x.area===compare),x=>x.area).slice(0,8);return <><div className="kpi-grid compact"><Kpi title="Filtered incidents" value={fmt(data.length)} change="Current" icon={{Component:Activity}} color="#3e92ff" caption="selected records"/><Kpi title="Categories present" value={String(cats.length)} change="Distribution" icon={{Component:Layers}} color="#00d5ff" caption="with reported records"/><Kpi title="High severity share" value={`${data.length?Math.round(data.filter(x=>(x.severity==='High'||x.severity==='Critical')).length/data.length*100):0}%`} change="Calculated" icon={{Component:AlertTriangle}} color="#ff8b74" caption="of filtered incidents"/><Kpi title="Dataset coverage" value={`${Math.round(data.length/Math.max(1,all.length)*100)}%`} change="Selection" icon={{Component:Filter}} color="#b69aff" caption="of seeded dataset"/></div><div className="dashboard-grid"><Card title="Incident trend" subtitle="Choose aggregation interval" className="span-2" action={<div className="segmented">{(['day','week','month'] as const).map(x=><button className={period===x?'active':''} key={x} onClick={()=>setPeriod(x)}>{x[0].toUpperCase()+x.slice(1)}</button>)}</div>}><div className="chart-wrap chart-large"><ResponsiveContainer width="100%" height="100%"><LineChart data={series}><CartesianGrid stroke="#203047" strokeDasharray="3 4" vertical={false}/><XAxis dataKey="name" tick={{fill:'#8092ad',fontSize:11}} axisLine={false} tickLine={false}/><YAxis tick={{fill:'#8092ad',fontSize:11}} axisLine={false} tickLine={false}/><ChartTooltip contentStyle={{background:'#0d1b30',border:'1px solid #263b56',borderRadius:9}}/><Line type="monotone" dataKey="incidents" stroke="#00d5ff" strokeWidth={2.4} dot={false} activeDot={{r:5}}/></LineChart></ResponsiveContainer></div></Card><Card title="Severity distribution" subtitle="Current filtered records"><div className="chart-wrap chart-medium"><ResponsiveContainer width="100%" height="100%"><BarChart data={severity} layout="vertical"><CartesianGrid stroke="#203047" strokeDasharray="3 4" horizontal={false}/><XAxis type="number" tick={{fill:'#8092ad',fontSize:11}} axisLine={false} tickLine={false}/><YAxis type="category" dataKey="name" tick={{fill:'#b7c6d9',fontSize:11}} axisLine={false} tickLine={false} width={65}/><ChartTooltip contentStyle={{background:'#0d1b30',border:'1px solid #263b56',borderRadius:9}}/><Bar dataKey="value" radius={[0,4,4,0]}>{severity.map((x,i)=><Cell key={i} fill={x.fill}/>)}</Bar></BarChart></ResponsiveContainer></div></Card><Card title="By weekday" subtitle="Reported day of week"><div className="chart-wrap chart-medium"><ResponsiveContainer width="100%" height="100%"><BarChart data={days}><CartesianGrid stroke="#203047" strokeDasharray="3 4" vertical={false}/><XAxis dataKey="name" tick={{fill:'#8092ad',fontSize:11}} axisLine={false} tickLine={false}/><YAxis tick={{fill:'#8092ad',fontSize:11}} axisLine={false} tickLine={false}/><ChartTooltip contentStyle={{background:'#0d1b30',border:'1px solid #263b56',borderRadius:9}}/><Bar dataKey="incidents" fill="#7b72ff" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></Card><Card title="Category breakdown" subtitle="Counts and relative share" className="span-2"><div className="category-bars">{cats.map(x=><div className="category-bar-row" key={x.name}><span>{x.name}</span><div><i style={{width:`${x.value/Math.max(1,...cats.map(c=>c.value))*100}%`}}/></div><b>{x.value}</b><small>{data.length?Math.round(x.value/data.length*100):0}%</small></div>)}</div></Card><Card title="Area comparison" subtitle="Select one area to inspect its distribution" action={<select className="compact-select" value={compare} onChange={e=>setCompare(e.target.value)}><option>All areas</option>{AREAS.map(x=><option key={x}>{x}</option>)}</select>}><div className="area-rank-list">{areaData.map((x,i)=><div key={x.name}><span className="rank">{String(i+1).padStart(2,'0')}</span><span>{x.name}</span><b>{x.value}</b></div>)}</div></Card></div><div className="disclaimer-strip"><ShieldAlert size={16}/><span>Temporal patterns describe this seeded synthetic dataset only. They should not be interpreted as real crime trends.</span></div></>}
function Hotspots({data,onSelectArea}:{data:Incident[];onSelectArea:(a:string)=>void}){const [cell,setCell]=useState('0.003'),[minimum,setMinimum]=useState('3'),[chosen,setChosen]=useState<number|null>(null);const hotspots=useMemo(()=>detectHotspots(data,Number(cell)).filter(x=>x.count>=Number(minimum)),[data,cell,minimum]);const h=hotspots[chosen??0];return <><div className="analysis-banner"><div className="analysis-banner-icon"><Radar size={23}/></div><div><b>Spatial grid aggregation</b><p>Incidents are grouped into latitude/longitude grid cells. Counts are repeatable for the current dataset and selected cell size.</p></div><span className="tiny-badge">METHOD · GRID COUNTS</span></div><div className="hotspot-layout"><Card title="Hotspot distribution" subtitle="Incident points with aggregated grid-cell outlines" className="hotspot-map-card"><div className="full-map hotspot-map"><CrimeMap data={data} selected={null} onSelect={()=>{}} zoom={12} heat/><div className="map-legend-panel"><b>GRID DENSITY</b><span><i style={{background:'#ff647c'}}/> High relative count</span><span><i style={{background:'#f7b955'}}/> Moderate count</span><small>Circles indicate grid aggregates, not official boundaries.</small></div></div></Card><Card title="Analysis parameters" subtitle="Change method inputs to recompute"><div className="parameter-form"><label>Grid cell size <select value={cell} onChange={e=>{setCell(e.target.value);setChosen(null)}}><option value="0.0015">Fine · 0.0015°</option><option value="0.003">Standard · 0.003°</option><option value="0.005">Broad · 0.005°</option><option value="0.008">Very broad · 0.008°</option></select><small>Approximate cell width varies by latitude.</small></label><label>Minimum incidents per cell<select value={minimum} onChange={e=>{setMinimum(e.target.value);setChosen(null)}}><option value="2">2 incidents</option><option value="3">3 incidents</option><option value="5">5 incidents</option><option value="8">8 incidents</option></select></label><div className="parameter-result"><span>Matching cells</span><b>{hotspots.length}</b></div><div className="parameter-result"><span>Incidents in current selection</span><b>{data.length}</b></div><div className="method-note"><CircleHelp size={15}/><span><b>How this works</b><br/>Each record is assigned to a grid cell using floor(latitude / cell size) and floor(longitude / cell size). Cells below the minimum count are omitted. This is not a validated predictive model.</span></div></div></Card></div><Card title="Detected hotspot cells" subtitle="Ranked by incident count · select a row for area review" action={<span className="tiny-badge">{hotspots.length} CELLS</span>}><div className="hotspot-table">{hotspots.length?hotspots.slice(0,20).map((x,i)=><button key={`${x.lat}-${x.lng}`} className={`hotspot-table-row ${chosen===i?'active':''}`} onClick={()=>setChosen(i)}><span className="rank">{String(i+1).padStart(2,'0')}</span><span className="hotspot-table-area"><b>{x.area}</b><small>{x.lat.toFixed(4)}, {x.lng.toFixed(4)}</small></span><span className="hotspot-table-meter"><i><span style={{width:`${x.intensity}%`}}/></i><small>Relative cell intensity</small></span><b>{x.count}</b><span className="muted-small">incidents</span><ArrowUpRight size={15}/></button>):<Empty text="No grid cells meet this minimum count. Try a broader cell size or lower threshold."/>}</div></Card>{h&&<Card title="Selected cell details" subtitle="Descriptive aggregate summary" action={<button className="btn btn-secondary btn-small" onClick={()=>onSelectArea(h.area)}>Review area <ArrowUpRight size={14}/></button>}><div className="hotspot-detail-grid"><div className="hotspot-detail-score"><small>INCIDENT COUNT</small><b>{h.count}</b><span>{h.area} · approximate cell centroid</span></div><div><small>CENTROID</small><b>{h.lat.toFixed(5)}, {h.lng.toFixed(5)}</b><small>Calculated from included records</small></div><div><small>TOP CATEGORY</small><b>{Object.entries(h.categories).sort((a,b)=>Number(b[1])-Number(a[1]))[0]?.[0]||'—'}</b><small>Most frequent within cell</small></div><div><small>SELECTION SHARE</small><b>{data.length?Math.round(h.count/data.length*100):0}%</b><small>Of currently filtered records</small></div></div></Card>}<div className="disclaimer-strip"><ShieldAlert size={16}/><span>Hotspot results are spatial aggregates over synthetic coordinates. They are not official hotspot designations or evidence of future incidents.</span></div></>}
function Correlation({data,all,onSelect,onOpenMap}:{data:Incident[];all:Incident[];onSelect:(x:Incident|null)=>void;onOpenMap:(x:Incident)=>void}){const [baseId,setBaseId]=useState(data[0]?.id||''),[radius,setRadius]=useState('2'),[hours,setHours]=useState('72'),[sameCategory,setSameCategory]=useState(false);const base=all.find(x=>x.id===baseId);const matches=useMemo(()=>base?relatedIncidents(base,all,Number(radius),Number(hours)).filter(x=>!sameCategory||x.incident.category===base.category):[],[base,all,radius,hours,sameCategory]);return <><div className="analysis-banner"><div className="analysis-banner-icon"><Crosshair size={23}/></div><div><b>Exploratory record similarity</b><p>Scores are deterministic and based only on geographic distance, timestamp proximity and optional category matching.</p></div><span className="tiny-badge">NO IDENTITY INFERENCE</span></div><div className="correlation-grid"><Card title="Reference incident" subtitle="Choose a record from the current filtered dataset"><label className="field-label">Reference record<select className="wide-select" value={baseId} onChange={e=>setBaseId(e.target.value)}>{data.map(x=><option key={x.id} value={x.id}>{x.id} — {x.category} · {x.area}</option>)}</select></label>{base?<IncidentDetails incident={base}/>:<Empty text="No incident is available in this selection."/>}</Card><Card title="Matching criteria" subtitle="Adjust the documented scoring parameters"><div className="parameter-form"><label>Geographic radius<select value={radius} onChange={e=>setRadius(e.target.value)}><option value="0.5">0.5 km</option><option value="1">1 km</option><option value="2">2 km</option><option value="5">5 km</option><option value="10">10 km</option></select></label><label>Time window<select value={hours} onChange={e=>setHours(e.target.value)}><option value="12">12 hours</option><option value="24">24 hours</option><option value="72">72 hours</option><option value="168">7 days</option><option value="720">30 days</option></select></label><label className="check-field"><input type="checkbox" checked={sameCategory} onChange={e=>setSameCategory(e.target.checked)}/> Only show same-category matches</label><div className="method-note"><CircleHelp size={15}/><span><b>Score formula</b><br/>45% geographic proximity + 35% time proximity + 20% category match. Each proximity component decreases linearly to zero at the configured limit. Results below 20% are hidden.</span></div></div></Card></div><Card title="Related incident candidates" subtitle={base?`Compared with ${base.id} · ${matches.length} candidates meet the score threshold`:'Select a reference incident to begin'} action={<span className="tiny-badge">EXPLORATORY ONLY</span>}>{matches.length? <div className="related-list">{matches.slice(0,30).map(m=><div className="related-row" key={m.incident.id}><div className="related-score"><b>{m.score}</b><small>score</small></div><div className="related-main"><b>{m.incident.id} <span className="category-chip">{m.incident.category}</span></b><small>{m.incident.area} · {new Date(m.incident.timestamp).toLocaleString()}</small><div className="reason-tags">{m.reasons.map((r,i)=><span key={i}>{r}</span>)}</div></div><button className="btn btn-secondary btn-small" onClick={()=>{onSelect(m.incident);onOpenMap(m.incident)}}>Open map <ArrowUpRight size={13}/></button></div>)}</div>:<Empty text="No candidates meet the current criteria. Try a wider radius or time window."/>}</Card><div className="disclaimer-strip"><ShieldAlert size={16}/><span>Similarity is not proof of a shared offender, criminal intent, causation or guilt. These scores are analytical aids for qualified human review only.</span></div></>}
function Risk({data,patrols,setPatrols,onNotice}:{data:Incident[];patrols:any[];setPatrols:(x:any[])=>void;onNotice:(s:string)=>void}){const [period,setPeriod]=useState('All time'),[category,setCategory]=useState('All categories'),[editId,setEditId]=useState<number|null>(null);const riskData=useMemo(()=>areaRisk(data.filter(x=>category==='All categories'||x.category===category)),[data,category]);const [draftArea,setDraftArea]=useState(AREAS[0]),[draftShift,setDraftShift]=useState('Evening · 16:00–00:00');const add=()=>{setPatrols([...patrols,{id:Date.now(),area:draftArea,shift:draftShift,priority:'Review',notes:'Proposed review'}]);onNotice('Patrol draft added. Save it by keeping this plan; no dispatch is made.')} ;return <><div className="analysis-banner"><div className="analysis-banner-icon"><Navigation size={23}/></div><div><b>Area-level review indicators</b><p>Scores combine relative incident volume, high/critical share and night-time share. These are descriptive indicators, not individual risk predictions.</p></div><span className="tiny-badge">HUMAN REVIEW REQUIRED</span></div><div className="risk-controls"><label>Analysis period<select value={period} onChange={e=>setPeriod(e.target.value)}><option>All time</option><option>Last 30 days</option><option>Last 90 days</option></select></label><label>Category focus<select value={category} onChange={e=>setCategory(e.target.value)}><option>All categories</option>{CATEGORIES.map(x=><option key={x}>{x}</option>)}</select></label><span><i className="pulse-dot"/> {data.length} records analyzed</span></div><div className="risk-layout"><Card title="Area review index" subtitle="Ranked from current filtered data" className="risk-rank-card"><div className="risk-list">{riskData.map((x,i)=><div className="risk-row" key={x.area}><span className="rank">{String(i+1).padStart(2,'0')}</span><div className="risk-area"><b>{x.area}</b><small>{x.count} incidents</small></div><div className="risk-bar"><i><span style={{width:`${x.score}%`,background:x.score>65?'#ff647c':x.score>40?'#f7b955':'#36d6a0'}}/></i><small>Index {x.score}/100</small></div><span className={`risk-level ${x.score>65?'high':x.score>40?'medium':'low'}`}>{x.score>65?'Higher':x.score>40?'Moderate':'Lower'}</span></div>)}</div></Card><Card title="How the index is calculated" subtitle="Transparent component breakdown"><div className="risk-formula"><div><span className="formula-color" style={{background:'#3989ff'}}/><div><b>Relative volume</b><small>Area count / maximum area count</small></div><strong>55%</strong></div><div><span className="formula-color" style={{background:'#ff8b74'}}/><div><b>High / critical share</b><small>Share of records marked High or Critical</small></div><strong>25%</strong></div><div><span className="formula-color" style={{background:'#b69aff'}}/><div><b>Night-time share</b><small>Records between 20:00 and 04:59</small></div><strong>20%</strong></div><div className="formula-total"><span>Combined descriptive index</span><b>0–100</b></div><p>Inputs are normalized within the currently selected records. No demographic or protected-characteristic inputs are used.</p></div></Card></div><Card title="Draft patrol review plan" subtitle="Editable planning suggestions · not dispatch orders" action={<span className="tiny-badge">LOCAL DRAFT</span>}><div className="patrol-add"><label>Area<select value={draftArea} onChange={e=>setDraftArea(e.target.value)}>{AREAS.map(x=><option key={x}>{x}</option>)}</select></label><label>Proposed shift<select value={draftShift} onChange={e=>setDraftShift(e.target.value)}><option>Morning · 06:00–14:00</option><option>Afternoon · 12:00–20:00</option><option>Evening · 16:00–00:00</option><option>Overnight · 00:00–08:00</option></select></label><button className="btn btn-primary" onClick={add}><Plus size={15}/> Add to draft</button><button className="btn btn-secondary" onClick={()=>{setPatrols([]);onNotice('Patrol draft cleared.')}}><RefreshCw size={14}/> Reset draft</button></div>{patrols.length?<div className="patrol-table-wrap"><table><thead><tr><th>AREA</th><th>PROPOSED SHIFT</th><th>PRIORITY</th><th>NOTES</th><th>ACTIONS</th></tr></thead><tbody>{patrols.map((p,i)=><tr key={p.id}><td>{editId===p.id?<select value={p.area} onChange={e=>setPatrols(patrols.map(z=>z.id===p.id?{...z,area:e.target.value}:z))}>{AREAS.map(x=><option key={x}>{x}</option>)}</select>:p.area}</td><td>{editId===p.id?<select value={p.shift} onChange={e=>setPatrols(patrols.map(z=>z.id===p.id?{...z,shift:e.target.value}:z))}><option>Morning · 06:00–14:00</option><option>Afternoon · 12:00–20:00</option><option>Evening · 16:00–00:00</option><option>Overnight · 00:00–08:00</option></select>:p.shift}</td><td><select value={p.priority} onChange={e=>setPatrols(patrols.map(z=>z.id===p.id?{...z,priority:e.target.value}:z))}><option>Review</option><option>Routine</option><option>Elevated review</option></select></td><td><input value={p.notes} onChange={e=>setPatrols(patrols.map(z=>z.id===p.id?{...z,notes:e.target.value}:z))}/></td><td><button className="text-action" onClick={()=>setEditId(editId===p.id?null:p.id)}>{editId===p.id?'Done':'Edit'}</button><button className="text-action danger-text" onClick={()=>setPatrols(patrols.filter(z=>z.id!==p.id))}>Remove</button></td></tr>)}</tbody></table></div>:<Empty text="No patrol-plan items yet. Add an area and shift to begin a local draft."/>}<div className="patrol-save-note"><ShieldAlert size={15}/> Drafts persist in this browser's local storage. They are planning notes only; nothing is sent to a dispatch system.</div></Card></>}
function Reports({data,filters,onNotice}:{data:Incident[];filters:Filters;onNotice:(s:string)=>void}){const [type,setType]=useState('Crime summary'),[recent,setRecent]=useState<any[]>(()=>{try{return JSON.parse(localStorage.getItem('cm-reports')||'[]')}catch{return[]}});const [title,setTitle]=useState('CrimeMap analytical summary');const categories=groupCount(data,x=>x.category),areas=groupCount(data,x=>x.area),hot=detectHotspots(data).slice(0,5),high=data.filter(x=>(x.severity==='High'||x.severity==='Critical')).length;const generate=()=>{if(!data.length){onNotice('No records match these filters. Adjust filters before generating a report.');return}const item={id:Date.now(),type,title,created:new Date().toLocaleString(),count:data.length};const next=[item,...recent].slice(0,10);setRecent(next);localStorage.setItem('cm-reports',JSON.stringify(next));onNotice('Report preview updated and saved to recent reports.')};const reportRows=type==='Temporal trends'?trend(data,'month'):type==='Hotspot report'?hot:type==='Area risk report'?areaRisk(data):type==='Incident correlation'?[]:data;const download=()=>{if(type==='Incident correlation'){onNotice('Choose an incident in the correlation workspace to calculate matches.');return}const rows=(Array.isArray(reportRows)?reportRows:[]) as Record<string,unknown>[];if(exportCSV(rows,`crimemap-${type.toLowerCase().replaceAll(' ','-')}.csv`))onNotice('CSV export started.');else onNotice('There is no data to export for this report.');};return <><div className="report-toolbar"><div><div className="eyebrow">REPORT BUILDER</div><h2>Build a clear, filter-aware report.</h2><p>Preview summaries and export data from the current selection.</p></div><button className="btn btn-primary" onClick={generate}><FileBarChart2 size={15}/> Generate report</button></div><div className="reports-layout"><Card title="Report configuration" subtitle="Select the report you want to preview"><label className="field-label">Report type<select className="wide-select" value={type} onChange={e=>setType(e.target.value)}>{['Crime summary','Temporal trends','Hotspot report','Area risk report','Incident correlation'].map(x=><option key={x}>{x}</option>)}</select></label><label className="field-label">Report title<input className="wide-input" value={title} onChange={e=>setTitle(e.target.value)}/></label><div className="report-filter-summary"><b>ACTIVE FILTERS</b><div><span>Date range</span><strong>{filters.from||'Start'} — {filters.to||'Latest'}</strong></div><div><span>Category</span><strong>{filters.category}</strong></div><div><span>Severity</span><strong>{filters.severity}</strong></div><div><span>Area</span><strong>{filters.area}</strong></div><div><span>Search</span><strong>{filters.search||'None'}</strong></div></div><div className="report-actions"><button className="btn btn-secondary" onClick={download}><Download size={15}/> Export report CSV</button><button className="btn btn-secondary" onClick={()=>window.print()}><FileBarChart2 size={15}/> Print / Save PDF</button></div><p className="small-note">Print opens your browser's print dialog. Choose “Save as PDF” to create a PDF.</p></Card><Card title="Report preview" subtitle={`Generated ${new Date().toLocaleString()} · synthetic demo data`} className="report-preview-card"><div className="report-paper"><div className="report-paper-head"><div className="brand-mark"><Shield size={19}/><span/></div><span>CRIMEMAP / ANALYTICS</span><small>DEMO REPORT</small></div><h2>{title||type}</h2><p className="report-subtitle">{type} · Filter-aware analytical preview</p><div className="report-paper-meta"><span>Generated<strong>{new Date().toLocaleDateString()}</strong></span><span>Records<strong>{data.length}</strong></span><span>Source<strong>Seeded synthetic dataset</strong></span></div><div className="report-summary-cards"><div><small>TOTAL RECORDS</small><b>{fmt(data.length)}</b></div><div><small>HIGH / CRITICAL</small><b>{fmt(high)}</b></div><div><small>AREAS PRESENT</small><b>{areas.length}</b></div></div><h3>{type==='Temporal trends'?'Monthly trend summary':type==='Hotspot report'?'Top aggregated cells':type==='Area risk report'?'Area review index':type==='Incident correlation'?'Correlation methodology':'Category breakdown'}</h3>{type==='Crime summary'?<div className="report-breakdown">{categories.map(x=><div key={x.name}><span>{x.name}</span><i><b style={{width:`${x.value/Math.max(1,...categories.map(c=>c.value))*100}%`}}/></i><strong>{x.value}</strong></div>)}</div>:type==='Hotspot report'?<div className="report-breakdown">{hot.length?hot.map((x:any,i)=><div key={i}><span>{x.area}</span><i><b style={{width:`${x.intensity}%`}}/></i><strong>{x.count}</strong></div>):<p>No qualifying grid cells.</p>}</div>:type==='Area risk report'?<div className="report-breakdown">{areaRisk(data).slice(0,6).map(x=><div key={x.area}><span>{x.area}</span><i><b style={{width:`${x.score}%`}}/></i><strong>{x.score}</strong></div>)}</div>:type==='Temporal trends'?<div className="report-breakdown">{trend(data,'month').slice(-8).map(x=><div key={x.name}><span>{x.name}</span><i><b style={{width:`${x.incidents/Math.max(1,...trend(data,'month').map(t=>t.incidents))*100}%`}}/></i><strong>{x.incidents}</strong></div>)}</div>:<p className="report-method">Similarity scores are calculated in the Incident Correlation workspace using 45% geographic proximity, 35% temporal proximity and 20% category match. This report preview does not calculate matches without a reference incident.</p>}<div className="report-warning"><ShieldAlert size={14}/><span>All incident records and derived findings are synthetic and illustrative. Not for operational decisions.</span></div><div className="report-paper-footer">CRIMEMAP INTELLIGENCE SUITE <span>CONFIDENTIALITY NOT ESTABLISHED · DEMO</span></div></div></Card></div><Card title="Recently generated reports" subtitle="Stored in this browser session" action={<span className="tiny-badge">{recent.length} REPORTS</span>}>{recent.length?<div className="recent-reports">{recent.map(x=><div key={x.id}><div className="recent-report-icon"><FileBarChart2 size={17}/></div><div><b>{x.title}</b><small>{x.type} · {x.created} · {x.count} records</small></div><button className="text-action" onClick={()=>{setType(x.type);setTitle(x.title);onNotice('Report configuration restored. Click Generate report to refresh the preview.')}}>Reopen <ArrowUpRight size={13}/></button></div>)}</div>:<Empty text="Generated reports will appear here. Create a report to start a history."/>}</Card><div className="disclaimer-strip"><ShieldAlert size={16}/><span>Exports reflect the currently filtered synthetic records. Avoid sharing as if they were official public-safety statistics.</span></div></>}

export default App;
